[FunctionName("ProcessBlob")]
public async Task Run(
    [BlobTrigger("uploads/{name}", Connection = "AzureWebJobsStorage")] Stream myBlob,
    [Queue("processed-items", Connection = "AzureWebJobsStorage")] IAsyncCollector<string> outputQueue,
    ILogger log)
{
    log.LogInformation("Processing blob: {Name}", name);
